import{_ as e,o as i,c as o,ah as a}from"./chunks/framework.D4KxWb5R.js";const h=JSON.parse('{"title":"Présentation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"src/guide/introduction.md"}'),r={name:"guide/introduction.md"};function n(s,t,d,u,c,l){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="presentation" tabindex="-1">Présentation <a class="header-anchor" href="#presentation" aria-label="Permalink to &quot;Présentation&quot;">​</a></h1><p>M&#39;City IQ est la plateforme interne de M&#39;City IQ Ltd. Elle réunit trois espaces, accessibles avec un seul compte :</p><ul><li><strong>le site public</strong> (<a href="https://mcityiq.com" target="_blank" rel="noreferrer">mcityiq.com</a>) : présentation de M&#39;City, de ses produits et de ses zones, formulaire de contact ;</li><li><strong>l&#39;intranet</strong> : votre bureau, les communications, les ressources partagées et un espace par produit ;</li><li><strong>le back-office M&#39;City</strong> : registre des produits et des zones, comptes, contenus du site, supervision et configuration, selon votre poste.</li></ul><p>Les <strong>produits</strong> exploités par M&#39;City, comme Auticway, ont chacun leur propre back-office. M&#39;City IQ n&#39;en gère jamais les opérations : il vous y donne accès par connexion unique (SSO) quand cet accès vous est accordé.</p><h2 id="qui-lit-quoi" tabindex="-1">Qui lit quoi <a class="header-anchor" href="#qui-lit-quoi" aria-label="Permalink to &quot;Qui lit quoi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vous êtes…</th><th>Lisez</th></tr></thead><tbody><tr><td>Membre de l&#39;équipe M&#39;City</td><td><a href="./getting-started.html">Bien démarrer</a>, <a href="./desk.html">Le bureau</a>, <a href="./notifications.html">Notifications</a>, <a href="./account.html">Mon compte</a></td></tr><tr><td>Concerné par un poste précis</td><td><a href="./positions.html">Selon votre poste</a></td></tr><tr><td>Administrateur (PDG, Pôle Exploitation, Pôle Support, RH)</td><td>La partie <a href="./administration/accounts.html">Administration</a></td></tr><tr><td>Utilisateur du back-office Auticway</td><td><a href="./auticway.html">Back-office Auticway</a></td></tr><tr><td>Équipe technique d&#39;un produit</td><td>La partie <a href="./integration/overview.html">Intégration technique</a></td></tr></tbody></table><h2 id="notions-a-connaitre" tabindex="-1">Notions à connaître <a class="header-anchor" href="#notions-a-connaitre" aria-label="Permalink to &quot;Notions à connaître&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Notion</th><th>Définition</th></tr></thead><tbody><tr><td>Poste</td><td>Votre profil de poste, parmi sept. Il décide des <strong>fonctions</strong> que vous voyez. Un compte n&#39;a qu&#39;un poste actif.</td></tr><tr><td>Périmètre</td><td>Les produits, zones et bureaux attribués à votre compte. Il décide des <strong>données</strong> que vous voyez dans ces fonctions.</td></tr><tr><td>Équipe</td><td>Groupe de comptes nommés, responsable d&#39;un ou plusieurs produits. Un compte peut appartenir à plusieurs équipes.</td></tr><tr><td>Zone</td><td>Zone urbaine ou périurbaine précise. Seule une zone <strong>qualifiée</strong> peut être rattachée à un produit.</td></tr><tr><td>Bureau</td><td>Implantation physique de M&#39;City, rattachée à une zone.</td></tr><tr><td>Département</td><td>Pôle ou volet de l&#39;organisation, utilisé pour cibler les communications.</td></tr><tr><td>Back-office produit</td><td>L&#39;outil d&#39;administration propre à un produit (ex. le back-office Auticway).</td></tr><tr><td>SSO</td><td>Connexion unique : votre compte M&#39;City ouvre l&#39;intranet, le back-office M&#39;City et les back-offices produits qui vous sont accordés.</td></tr><tr><td>Administrateur général</td><td>Le PDG, ou un compte délégué : il invite les comptes et gère la configuration.</td></tr></tbody></table><h2 id="langues" tabindex="-1">Langues <a class="header-anchor" href="#langues" aria-label="Permalink to &quot;Langues&quot;">​</a></h2><p>L&#39;interface existe en anglais et en français. Vous choisissez votre langue de travail dans <a href="./account.html#langue">Mon compte</a> ; elle s&#39;applique à tout l&#39;intranet et à vos notifications. Les contenus publiés (communications, ressources, pages du site) sont saisis en anglais et en français ; quand le français manque, le texte anglais s&#39;affiche.</p>',10)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
